<script setup lang="ts">import{Check,Crown,LoaderCircle}from"lucide-vue-next";definePageMeta({layout:"dashboard",middleware:"auth"});const{tr}=useAppPreferences();const{data,status}=await useFetch<any>("/api/subscription");const money=(v:any)=>new Intl.NumberFormat().format(Number(v||0));const days=computed(()=>data.value?.subscription?.endsAt?Math.max(0,Math.ceil((new Date(data.value.subscription.endsAt).getTime()-Date.now())/86400000)):0);</script><template><div><PageHeader :title="tr('اشتراک و پرداخت','Subscription & billing')" :description="tr('پلن، محدودیت‌ها و سوابق پرداخت واقعی حساب.','Your real plan, limits, and payment history.')"/><div v-if="status==='pending'" class="surface grid h-60 place-items-center"><LoaderCircle class="animate-spin"/></div><template v-else><section v-if="data?.subscription" class="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><article class="relative overflow-hidden rounded-3xl bg-gradient-to-br from-violet-600 to-indigo-800 p-7 text-white shadow-xl"><Crown class="absolute -end-8 -top-8 size-40 text-white/5"/><span class="badge bg-white/10 text-violet-100">{{data.subscription.status}}</span><h2 class="mt-5 text-2xl font-black">{{data.subscription.plan.name}}</h2><p class="mt-2 text-sm text-violet-200">{{tr('روز باقی‌مانده','days remaining')}}: {{days}}</p><div class="mt-8 flex items-end gap-2"><b class="text-3xl">{{money(data.subscription.plan.price)}}</b><span class="text-sm text-violet-200">{{tr('تومان','IRR')}} / {{data.subscription.plan.durationDays}} {{tr('روز','days')}}</span></div></article><article class="surface p-6"><h2 class="font-black">{{tr('محدودیت‌های پلن','Plan limits')}}</h2><ul class="mt-5 space-y-4"><li v-for="x in [`${data.subscription.plan.maxWhatsAppConnections} WhatsApp`,`${money(data.subscription.plan.maxMessages)} ${tr('پیام','messages')}`,`${money(data.subscription.plan.maxAIRequests)} AI`,`${data.subscription.plan.maxWebhooks} Webhook`]" :key="x" class="flex items-center gap-3 text-sm"><span class="grid size-6 place-items-center rounded-full bg-brand-50 text-brand-600"><Check :size="14"/></span>{{x}}</li></ul></article></section><section v-else class="surface p-8 text-center"><Crown class="mx-auto text-slate-300" :size="48"/><h2 class="mt-4 font-black">{{tr('اشتراک فعالی ندارید','No active subscription')}}</h2></section><section class="surface mt-5 overflow-hidden"><header class="border-b p-5"><h2 class="font-black">{{tr('تاریخچه سفارش‌ها','Order history')}}</h2></header><div v-if="!data?.orders.length" class="muted p-8 text-center">{{tr('سفارشی ثبت نشده است.','No orders yet.')}}</div><div v-for="order in data?.orders" :key="order.id" class="grid gap-3 border-b p-5 sm:grid-cols-4"><code>{{order.id.slice(-10)}}</code><span>{{new Date(order.createdAt).toLocaleDateString()}}</span><b>{{money(order.amount)}} {{tr('تومان','IRR')}}</b><span class="badge w-fit" :class="order.status==='PAID'?'bg-emerald-50 text-emerald-600':'bg-amber-50 text-amber-600'">{{order.status}}</span></div></section><section class="mt-5 grid gap-4 md:grid-cols-3"><article v-for="plan in data?.plans" :key="plan.id" class="surface p-5"><h3 class="font-black">{{plan.name}}</h3><b class="mt-3 block text-xl">{{money(plan.price)}} {{tr('تومان','IRR')}}</b><ul class="muted mt-4 text-sm"><li v-for="f in plan.features" :key="f">✓ {{f}}</li></ul><button class="btn btn-secondary mt-5 w-full" disabled>{{tr('درگاه پرداخت هنوز تنظیم نشده','Payment gateway not configured')}}</button></article></section></template></div></template>
